          MW*Sqrt[\[Xi]w]}, {0, 1, 1}])/(MW^2*(-1 + \[Xi]w)^3*
        (-MZ^2 + MW^2*\[Xi]w)*(MW^2*\[Xi]w - MZ^2*\[Xi]z)) + 
      (\[Xi]w*\[Xi]z*sorttad[{0, MW*Sqrt[\[Xi]w], MZ*Sqrt[\[Xi]z]}, 
         {0, 1, 1}])/((-1 + \[Xi]w)*(-1 + \[Xi]z)*(-MW^2 + MZ^2*\[Xi]z)^2*
        (-(MW^2*\[Xi]w) + MZ^2*\[Xi]z))))/(256*cw^2*d*MH^2*Pi^8*sw^2))
